import PropTypes from "prop-types";
import {
  Tooltip,
  Stack,
  TextField,
  MenuItem,
  Autocomplete,
  Paper,
} from "@mui/material";
import { LoadingButton } from "@mui/lab";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
// components
import Iconify from "../../../../components/Iconify";
import CurrencyPopover from "src/layouts/dashboard/header/CurrencyPopover";
import { useTranslation } from "react-i18next";
// ----------------------------------------------------------------------

const INPUT_WIDTH = 280;
const CONTROL_ITEM_SX = {
  textTransform: "capitalize",
  maxWidth: { md: INPUT_WIDTH },
  flex: "1 1 220px",
  minWidth: 180,
};
const DATE_PICKER_SX = {
  flex: "1 1 220px",
  minWidth: 200,
};
const FIELD_STYLE = {
  borderRadius: 3,
  backgroundColor: (theme) => theme.palette.background.paper,
  "& .MuiOutlinedInput-notchedOutline": {
    borderColor: "rgba(145, 158, 171, 0.32)",
  },
};

TicketTableToolbar.propTypes = {
  filterName: PropTypes.string,
  filterUser: PropTypes.string,
  filterMasterUser: PropTypes.string,
  filterProvider: PropTypes.string,
  onFilterProvider: PropTypes.func,
  providers: PropTypes.any,
  filterEndDate: PropTypes.instanceOf(Date),
  filterStartDate: PropTypes.instanceOf(Date),
  onFilterName: PropTypes.func,
  onFilterEndDate: PropTypes.func,
  onFilterUser: PropTypes.func,
  onFilterMasterUser: PropTypes.func,
  onFilterStartDate: PropTypes.func,
  users: PropTypes.array,
  selectsupervisors: PropTypes.array,
  loadText: PropTypes.string,
  viewReportText: PropTypes.string,
  title: PropTypes.string,
  handleRefresh: PropTypes.func,
  handlePrint: PropTypes.func,
  isLoading: PropTypes.bool,
  isReportNotFound: PropTypes.bool,
};

export default function TicketTableToolbar({
  users,
  selectsupervisors,
  filterStartDate,
  filterEndDate,
  filterUser,
  filterMasterUser,
  filterProvider,
  onFilterProvider,
  providers,
  onFilterUser,
  onFilterMasterUser,
  onFilterStartDate,
  onFilterEndDate,
  loadText = "Load",
  viewReportText = "Preview",
  title = "Filter list",
  handleRefresh,
  handlePrint,
  isLoading,
  isReportNotFound,
}) {
  const { t } = useTranslation();
  const supervisorOptions = selectsupervisors?.data ?? [];
  const selectedUser = users?.find((usr) => usr.uid === filterUser) || null;
  const selectedSupervisor =
    supervisorOptions.find((usr) => usr.uid === filterMasterUser) || null;
  return (
    <Paper
      elevation={0}
      sx={{
        borderRadius: 3,
        p: { xs: 2, md: 3 },
        boxShadow: (theme) => theme.shadows[4],
        backgroundColor: "background.default",
      }}
    >
      <Stack spacing={2}>
        <Stack
          direction="row"
          spacing={2}
          flexWrap="wrap"
          alignItems="center"
        >
          <CurrencyPopover />
          <TextField
            fullWidth
            select
            label={t("field.operator")}
            value={filterProvider}
            onChange={onFilterProvider}
            SelectProps={{
              MenuProps: {
                sx: { "& .MuiPaper-root": { maxHeight: 260 } },
              },
            }}
            sx={{ ...CONTROL_ITEM_SX, ...FIELD_STYLE }}
          >
            <MenuItem
              key="ALL"
              value=""
              sx={{
                mx: 1,
                my: 0.5,
                borderRadius: 0.75,
                typography: "body2",
                textTransform: "uppercase",
                fontWeight: "bold",
              }}
            >
              {t("params.all")}
            </MenuItem>
            {providers?.map((provide) => (
              <MenuItem
                key={provide}
                value={provide}
                sx={{
                  mx: 1,
                  my: 0.5,
                  borderRadius: 0.75,
                  typography: "body2",
                  textTransform: "capitalize",
                }}
              >
                {provide}
              </MenuItem>
            ))}
          </TextField>

          <Autocomplete
            options={supervisorOptions}
            value={selectedSupervisor}
            onChange={(_, newValue) =>
              onFilterMasterUser({ target: { value: newValue?.uid ?? "" } })
            }
            isOptionEqualToValue={(option, value) => option?.uid === value?.uid}
            getOptionLabel={(option) => option?.full_name ?? ""}
            clearOnEscape
            ListboxProps={{
              sx: { maxHeight: 260 },
            }}
            sx={{
              ...CONTROL_ITEM_SX,
              flexBasis: 230,
            }}
            paperComponent={(props) => (
              <Paper {...props} elevation={3} sx={{ borderRadius: 2 }} />
            )}
            renderInput={(params) => (
              <TextField
                {...params}
                label={t("field.supervisor")}
                sx={{ ...FIELD_STYLE, textTransform: "capitalize" }}
              />
            )}
          />

          <Autocomplete
            options={users ?? []}
            value={selectedUser}
            onChange={(_, newValue) =>
              onFilterUser({ target: { value: newValue?.uid ?? "" } })
            }
            isOptionEqualToValue={(option, value) => option?.uid === value?.uid}
            getOptionLabel={(option) => option?.full_name ?? ""}
            ListboxProps={{
              sx: { maxHeight: 260 },
            }}
            sx={{
              ...CONTROL_ITEM_SX,
              flexBasis: 240,
            }}
            paperComponent={(props) => (
              <Paper {...props} elevation={3} sx={{ borderRadius: 2 }} />
            )}
            renderInput={(params) => (
              <TextField
                {...params}
                label={t("field.user")}
                sx={{ ...FIELD_STYLE, textTransform: "capitalize" }}
              />
            )}
          />
        </Stack>

        <Stack
          direction="row"
          spacing={2}
          flexWrap="wrap"
          alignItems="center"
          justifyContent="space-between"
        >
          <Stack
            direction="row"
            spacing={2}
            flex="1 1 auto"
            flexWrap="wrap"
            alignItems="center"
          >
            <DatePicker
              label={t("field.start_date")}
              value={filterStartDate}
              onChange={onFilterStartDate}
              sx={DATE_PICKER_SX}
              renderInput={(params) => (
                <TextField {...params} fullWidth sx={FIELD_STYLE} />
              )}
            />

            <DatePicker
              label={t("field.end_date")}
              value={filterEndDate}
              onChange={onFilterEndDate}
              sx={DATE_PICKER_SX}
              renderInput={(params) => (
                <TextField {...params} fullWidth sx={FIELD_STYLE} />
              )}
            />
          </Stack>

          <Stack direction="row" spacing={2} alignItems="center">
            <Tooltip title={title}>
              <span>
                <LoadingButton
                  startIcon={<Iconify icon={"ic:round-filter-list"} />}
                  variant="contained"
                  onClick={handleRefresh}
                  loading={isLoading}
                  size="large"
                >
                  {loadText}
                </LoadingButton>
              </span>
            </Tooltip>
            {!isReportNotFound && (
              <Tooltip title="Effectuer Report">
                <span>
                  <LoadingButton
                    loading={isLoading}
                    variant="contained"
                    color="secondary"
                    onClick={handlePrint}
                    size="large"
                  >
                    {viewReportText}
                  </LoadingButton>
                </span>
              </Tooltip>
            )}
          </Stack>
        </Stack>
      </Stack>
    </Paper>
  );
}
